#include <stdio.h>
#include <stdlib.h>
int main(){
 FILE*f=fopen("/app/image.ppm","r");
 if(!f){perror("open");return 1;}
 char m[8]; int W,H,Mx;
 if(fscanf(f,"%7s %d %d %d ",m,&W,&H,&Mx)!=4){printf("hdr fail\n");return 1;}
 printf("magic=%s W=%d H=%d max=%d\n",m,W,H,Mx);
 long n=(long)W*H;
 long rsum=0,gsum=0,bsum=0;
 int r,g,b; int rmin=999,gmin=999,bmin=999,rmax=-1,gmax=-1,bmax=-1;
 // sample rows
 int *rows=NULL;
 // read all
 for(long i=0;i<n;i++){
  if(fscanf(f,"%d %d %d",&r,&g,&b)!=3){printf("read fail at %ld\n",i);return 1;}
  rsum+=r;gsum+=g;bsum+=b;
  if(r<rmin)rmin=r; if(r>rmax)rmax=r;
  if(g<gmin)gmin=g; if(g>gmax)gmax=g;
  if(b<bmin)bmin=b; if(b>bmax)bmax=b;
  // print some pixels
  if(i==0) printf("px0=%d %d %d\n",r,g,b);
  if(i==W/2) printf("top-mid=%d %d %d\n",r,g,b);
  if(i==(long)W*H/2+W/2) printf("mid=%d %d %d\n",r,g,b);
  if(i==n-1) printf("last=%d %d %d\n",r,g,b);
 }
 printf("avg=%.1f %.1f %.1f\n",(double)rsum/n,(double)gsum/n,(double)bsum/n);
 printf("ranges R[%d,%d] G[%d,%d] B[%d,%d]\n",rmin,rmax,gmin,gmax,bmin,bmax);
 // second pass for distinct colors count? sample
 fclose(f);
 // check center region and corners
 f=fopen("/app/image.ppm","r");
 char hdr[64]; fgets(hdr,64,f); // P3
 // need to skip? easier reopen and parse again for specific coords
 fclose(f);
 return 0;
}
EOF
