 printf("y=299 mid row:\n");
 for(int i=0;i<9;i++){int x=xs[i],y=299,idx=PX(x,y);printf(" (%d,299)=%d %d %d",x,R[idx],G[idx],B[idx]);}printf("\n");
 printf("y=599 bottom row:\n");
 for(int i=0;i<9;i++){int x=xs[i],y=599,idx=PX(x,y);printf(" (%d,599)=%d %d %d",x,R[idx],G[idx],B[idx]);}printf("\n");
 printf("center column x=400 varying y:\n");
 for(int y=0;y<600;y+=60){int idx=PX(400,y);printf(" y=%d %d %d %d\n",y,R[idx],G[idx],B[idx]);}
 printf("middle row y=300 varying x step 40:\n");
 for(int x=0;x<800;x+=40){int idx=PX(x,300);printf(" x=%d %d %d %d\n",x,R[idx],G[idx],B[idx]);}
