{"content":"#include <stdio.h>
#include <stdlib.h>
#include <math.h>
typedef struct{float x,y,z;}V;
V mk(float x,float y,float z){V v={x,y,z};return v;}
V add(V a,V b){return mk(a.x+b.x,a.y+b.y,a.z+b.z);}
V sub(V a,V b){return mk(a.x-b.x,a.y-b.y,a.z-b.z);}
V mul(V a,float t){return mk(a.x*t,a.y*t,a.z*t);}
float dot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
float len(V a){return sqrtf(dot(a,a));}
V norm(V a){float l=len(a);return mk(a.x/l,a.y/l,a.z/l);}
int main(){
 int W=800,H=600;
 fprintf(stderr,"Creating high-resolution image: %dx%d\n",W,H);
 fwrite("This will be downsampled with ffmpeg after rendering\n",1,53,stderr);
 V**img=(V**)malloc(sizeof(V*)*H);
 for(int j=0;j<H;j++) img[j]=(V*)malloc(sizeof(V)*W);
 fwrite("Rendering high-resolution image...\n",1,35,stderr);
 V light=norm(mk(1,1,-1));
 V sc=mk(0,-0.5,-5); float sr=1;
 float py=-1.5;
 for(int y=0;y<H;y++){
  fprintf(stderr,"\rProgress: %.1f%%",y*100.0f/600.0f);
  for(int x=0;x<W;x++){
   float vx=-1.3333334f + x/799.0f*2.6666667f;
   float vy=1.0f - y/599.0f*2.0f;
   V d=norm(mk(vx,vy,-1));
   V o=mk(0,0,0);
   V oc=sub(o,sc);
   float a=dot(d,d);
   float b=2*dot(oc,d);
   float c=dot(oc,oc)-sr*sr;
   float disc=b*b-4*a*c;
   float st=-1; int sh=0; V sn={0,0,0}; V sp={0,0,0};
   if(disc>0){
    float sq=sqrt(disc);
    float t=(-b-sq)/(2*a);
    if(t>0.001){st=t;sh=1; sp=add(o,mul(d,t)); sn=norm(sub(sp,sc));}
    else { t=(-b+sq)/(2*a); if(t>0.001){st=t;sh=1; sp=add(o,mul(d,t)); sn=norm(sub(sp,sc));} }
   }
   float pt=-1; int ph=0;
   if(fabs(d.y)>0.0001){
    float t=(py-o.y)/d.y;
    if(t>0.001&&(st<0||t<st)){pt=t;ph=1;sh=0;}
   }
   V col;
   if(sh){
    float df=fmax(dot(sn,light),0);
    float s=0.8*df+0.2;
    V so=add(sp,mul(sn,0.001));
    V oc2=sub(so,sc);
    float b2=2*dot(oc2,light);
    float c2=dot(oc2,oc2)-sr*sr;
    float disc2=b2*b2-4*c2;
    int insh=0;
    if(disc2>0){
     float sq=sqrt(disc2);
     float t=(-b2-sq)/2;
     if(t>0.001) insh=1;
     else { t=(-b2+sq)/2; if(t>0.001) insh=1; }
    }
    if(insh) s=0.2;
    col=mk(s,0.2*s,0.2*s);
   } else if(ph){
    V hp=add(o,mul(d,pt));
    int cx=(int)floor(hp.x), cz=(int)floor(hp.z);
    int sum=cx+cz;
    float al=(sum&1)==0?0.9:0.4;
    float df=fmax(dot(mk(0,1,0),light),0);
    float s=0.8*df+0.2;
    V so=add(hp,mk(0,0.001,0));
    V oc2=sub(so,sc);
    float b2=2*dot(oc2,light);
    float c2=dot(oc2,oc2)-sr*sr;
    float disc2=b2*b2-4*c2;
    int insh=0;
    if(disc2>0){
     float sq=sqrt(disc2);
     float t=(-b2-sq)/2;
     if(t>0.001) insh=1;
     else { t=(-b2+sq)/2; if(t>0.001) insh=1; }
    }
    if(insh) s=0.2;
    col=mk(al*s,al*s,al*s);
   } else {
    float t=(d.y+1)*0.5f;
    float r=t*0.5f+(1-t);
    float g=t*0.7f+(1-t);
    col=mk(r,g,1);
   }
   img[y][x]=col;
  }
 }
 fwrite("\nRendering complete\n",1,20,stderr);
 FILE*f=fopen("image.ppm","w");
 fprintf(f,"P3\n%d %d\n255\n",W,H);
 for(int y=0;y<H;y++) for(int x=0;x<W;x++){
  V c=img[y][x];
  int r=(int)(fmax(0,fmin(1,c.x))*255.99);
  int g=(int)(fmax(0,fmin(1,c.y))*255.99);
  int b=(int)(fmax(0,fmin(1,c.z))*255.99);
  fprintf(f,"%d %d %d\n",r,g,b);
 }
 fclose(f);
 fprintf(stderr,"Wrote image to %s\n","image.ppm");
 for(int y=0;y<H;y++) free(img[y]); free(img);
 fwrite("Done.\n",1,6,stderr);
 return 0;
}
